// Compiles the registrar annproc generates for many entities: a project with hundreds
// of entities must not hit the JVM limits on method size (64 KB of bytecode) or on the
// constant pool of one class. The entities are generated by a task, then processed by
// annproc like hand-written ones.
plugins {
    kotlin("jvm")
    id("com.google.devtools.ksp") version "2.2.21-2.0.5"
}

group = parent?.group ?: error("Group is not defined")
version = parent?.version ?: error("Version is not defined")

kotlin {
    jvmToolchain(8)
}

ksp {
    arg("stormify.generatedPackage", "test.large.generated")
}

val entityCount = 400
val generatedEntities = layout.buildDirectory.dir("generated/large-entities")

val generateLargeEntities by tasks.registering {
    inputs.property("count", entityCount)
    outputs.dir(generatedEntities)
    doLast {
        val dir = generatedEntities.get().dir("test/large/entities").asFile
        dir.deleteRecursively()
        dir.mkdirs()
        // Enums are registered by the registrar too: one per ten entities.
        for (e in 1..entityCount / 10)
            dir.resolve("Status$e.kt").writeText("package test.large.entities\n\nenum class Status$e { OPEN, CLOSED }\n")
        for (i in 1..entityCount) {
            val ref = if (i > 1) "    var parent: Entity${i - 1}? = null\n" else ""
            dir.resolve("Entity$i.kt").writeText(
                """
                |package test.large.entities
                |
                |import onl.ycode.stormify.DbField
                |import onl.ycode.stormify.DbTable
                |
                |@DbTable(name = "large_entity_$i")
                |class Entity$i {
                |    @DbField(primaryKey = true, primarySequence = "large_seq_$i") var id: Long? = null
                |    @DbField(name = "code_$i") var code: String? = null
                |    var title: String? = null
                |    var description: String? = null
                |    var amount: java.math.BigDecimal? = null
                |    var quantity: Int? = null
                |    var total: Long? = null
                |    var ratio: Double? = null
                |    var active: Boolean? = null
                |    var created: java.util.Date? = null
                |    var modified: java.util.Date? = null
                |    var notes: String? = null
                |    var category: String? = null
                |    var region: String? = null
                |    var owner: String? = null
                |    var status: Status${(i - 1) / 10 + 1}? = null
                |$ref}
                |""".trimMargin()
            )
        }
    }
}

kotlin.sourceSets.named("test") {
    kotlin.srcDir(generatedEntities)
}

tasks.matching { it.name == "kspTestKotlin" }.configureEach {
    dependsOn(generateLargeEntities)
    outputs.upToDateWhen { false }
}
tasks.matching { it.name == "compileTestKotlin" }.configureEach { dependsOn(generateLargeEntities) }

dependencies {
    testImplementation(project(":stormify"))
    testImplementation("org.xerial:sqlite-jdbc:3.47.2.0")
    testImplementation(kotlin("test"))
    add("kspTest", project(":annproc"))
}

tasks.test {
    // The registrar of hundreds of entities loads slowly under the default heap on CI.
    maxHeapSize = "512m"
}
